parameters.jsCode:
// 1. Target the incoming data from the active item loop
const items = $json;

// 2. Fix: Grab text from conversationalReply first, then fallback to output
const messageText = items.conversationalReply || items.output || "";

// 3. Fallback to your current state tracking routing type
let determinedType = items["Message Type"] || "audio";

// 4. Convert text to lowercase once for accurate string checking
const lowerText = messageText.toLowerCase();

// 5. Check Rule A: Explicit Clinic Action JSON Intents
const hasJsonIntent = lowerText.includes("booking confirmed") || 
                      lowerText.includes("booking rescheduled") || 
                      lowerText.includes("booking cancelled");

// 6. Check Rule B: Core Patient & Clinic Confirmation Headers
const hasSummaryLayout = lowerText.includes("patient name:") || 
                         lowerText.includes("mobile number:") || 
                         lowerText.includes("confirmation summary:") ||
                         lowerText.includes("shall i book?") ||
                         lowerText.includes("reply yes to proceed");

// 7. Check Rule C: Slot Availability Announcements (Updated with your live text)
const hasSlotList = lowerText.includes("available slots") || 
                    lowerText.includes("slot on") || 
                    lowerText.includes("is unavailable") ||
                    lowerText.includes("select the number corresponding");

// 8. If any structured confirmation layout or slot list matches, force Text route
if (hasJsonIntent || hasSummaryLayout || hasSlotList) {
    determinedType = "text";
}

// 9. Output the clean object back, passing conversationalReply forward safely
return {
    "conversationalReply": items.conversationalReply || "",
    "output": messageText,
    "Message Type": determinedType,
    "Customer Number": items["Customer Number"] || "",
    "Session ID": items["Session ID"] || "",
    "Current_Department": items["Current_Department"] || "Clinic Deptt"
};

// 1. Get Base64 from Gemini
const base64Data = $json.candidates[0].content.parts[0].inlineData.data;
const pcmBuffer = Buffer.from(base64Data, 'base64');

// 2. Create WAV Header (44 bytes) so Cloudinary recognizes it
const wavHeader = Buffer.alloc(44);
wavHeader.write('RIFF', 0);
wavHeader.writeUInt32LE(36 + pcmBuffer.length, 4);
wavHeader.write('WAVE', 8);
wavHeader.write('fmt ', 12);
wavHeader.writeUInt32LE(16, 16);
wavHeader.writeUInt16LE(1, 20); // PCM format
wavHeader.writeUInt16LE(1, 22); // Mono
wavHeader.writeUInt32LE(24000, 24); // Sample Rate (Gemini is 24kHz)
wavHeader.writeUInt32LE(24000 * 2, 28); // Byte Rate
wavHeader.writeUInt16LE(2, 32); // Block Align
wavHeader.writeUInt16LE(16, 34); // Bits per sample
wavHeader.write('data', 36);
wavHeader.writeUInt32LE(pcmBuffer.length, 40);

// 3. Combine Header + Raw Data
const finalBuffer = Buffer.concat([wavHeader, pcmBuffer]);

// 4. Register as a file for Cloudinary
const binaryData = await this.helpers.prepareBinaryData(
    finalBuffer, 
    'appointment_voice.mp3', 
    'audio/mpeg'
);

return [
  {
    json: { resource_type: "video" },
    binary: { data: binaryData }
  }
];

function convertTimeTo24h(timeStr) {
  if (!timeStr) return "00:00";
  timeStr = String(timeStr).trim();

  // 24-hour format: "15:15" or "15:15:00"
  const match24h = timeStr.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
  if (match24h) {
    const hours   = String(parseInt(match24h[1], 10)).padStart(2, '0');
    const minutes = match24h[2];
    return `${hours}:${minutes}`;
  }

  // 12-hour format: "4:00 PM" or "04:00 AM"
  const match12h = timeStr.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  if (match12h) {
    let hours      = parseInt(match12h[1], 10);
    const minutes  = match12h[2];
    const period   = match12h[3].toUpperCase();
    if (period === 'AM') { if (hours === 12) hours = 0; }
    else                 { if (hours !== 12) hours += 12; }
    return `${String(hours).padStart(2, '0')}:${minutes}`;
  }

  return "00:00";
}

function buildISO(dateStr, timeFormatted, tzOffset = "+05:00") {
  if (!dateStr || !timeFormatted) return null;
  // Append ":00" seconds only for ISO (Google Calendar requires HH:MM:SS)
  return `${dateStr}T${timeFormatted}:00${tzOffset}`;
}

function extractBooking(raw) {
  if (!raw) return null;
  if (typeof raw === 'object' && !Array.isArray(raw) && raw.intent) return raw;
  if (typeof raw !== 'string') return null;

  const str = raw.trim();

  if (str.startsWith('{')) {
    try {
      const parsed = JSON.parse(str);
      if (parsed && parsed.intent) return parsed;
    } catch (e) {}
  }

  const firstBrace = str.indexOf('{');
  const lastBrace  = str.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace > firstBrace) {
    try {
      const parsed = JSON.parse(str.slice(firstBrace, lastBrace + 1));
      if (parsed && parsed.intent) return parsed;
    } catch (e) {}
  }

  return null;
}

// ========================================
// MAIN LOGIC
// ========================================

const item    = $input.first();
const raw     = item.json.output;
const booking = extractBooking(raw);

// CASE 1: Plain chat
if (!booking) {
  const plainText = (typeof raw === 'string') ? raw : JSON.stringify(raw ?? "");
  return [{
    json: {
      isIntent             : false,
      intent               : "normal chat",
      patientName          : null,
      mobile               : null,
      department           : null,
      doctorName           : null,
      issue                : null,
      age                  : null,
      gender               : null,
      fee                  : null,
      calendarId           : null,
      appointmentDate      : null,
      startTimeFormatted   : "00:00",
      endTimeFormatted     : "00:00",
      startISO             : null,
      endISO               : null,
      conversationalReply  : plainText,
    }
  }];
}

// CASE 2: Booking JSON
const intentRaw       = (booking.intent || "").toLowerCase().trim();
const isIntent        = intentRaw === "booking confirmed";

const patientName     = booking.patientName  || null;
const mobile          = booking.mobile       || null;
const department      = booking.department   || null;
const doctorName      = booking.doctorName   || null;
const issue           = booking.issue        || null;
const age             = booking.age          || null;
const gender          = booking.gender       || null;
const appointmentDate = booking.date         || null;
const calendarId      = booking.calendarId   || null;

// ✅ Fee with PKR suffix
const rawFee = booking.fee;
const fee    = rawFee ? `${rawFee} PKR` : null;

// ✅ Time without seconds: "16:00", "16:15"
const startTimeFormatted = convertTimeTo24h(booking.startTime);
const endTimeFormatted   = convertTimeTo24h(booking.endTime);

// ISO keeps seconds for Google Calendar: "2026-06-27T16:00:00+05:00"
const startISO = buildISO(appointmentDate, startTimeFormatted, "+05:00");
const endISO   = buildISO(appointmentDate, endTimeFormatted,   "+05:00");

const conversationalReply = JSON.stringify(booking);

return [{
  json: {
    isIntent,
    intent: intentRaw,
    patientName,
    mobile,
    department,
    doctorName,
    issue,
    age,
    gender,
    fee,                      // ✅ "1200 PKR"
    calendarId,
    appointmentDate,
    startTimeFormatted,       // ✅ "16:00"
    endTimeFormatted,         // ✅ "16:15"
    startISO,                 // "2026-06-27T16:00:00+05:00"  (Google Calendar)
    endISO,                   // "2026-06-27T16:15:00+05:00"  (Google Calendar)
    conversationalReply,
  }
}];
